// ❌ OLD: Webpack configuration with babel/ts-loader and minifiers.
const path = require('path');
const TerserPlugin = require('terser-webpack-plugin');

module.exports = {
  entry: './src/index.ts',
  module: {
    rules: [
      { test: /\.tsx?$/, use: 'ts-loader', exclude: /node_modules/ }
    ]
  },
  optimization: {
    minimize: true,
    minimizer: [new TerserPlugin()]
  },
  output: {
    filename: 'bundle.js',
    path: path.resolve(__dirname, 'dist')
  }
};

// ✅ NEW: Bun native bundler script with built-in TS/JSX transpilation and minification.
const result = await Bun.build({
  entrypoints: ['./src/index.ts'],
  outdir: './dist',
  target: 'browser',
  minify: true,
  splitting: true,
  sourcemap: 'external'
});

if (!result.success) {
  console.error('Build failed', result.logs);
} else {
  console.log(`Successfully built ${result.outputs.length} chunks!`);
}
